  if (body.error) {
    return [{
      json: {
        success: false,
        error: { code: 'CLAUDE_ERROR', message: body.error.message || 'Claude API error' }
      }
    }];
  }

  const content = body.content?.[0]?.text || '';
  const usage = body.usage || {};

  if (!content) {
    return [{
      json: {
        success: false,
        error: { code: 'EMPTY_RESPONSE', message: 'Claude returned empty response' }
      }
    }];
  }

  // RFC: indicate if EN pivot was used
  const usedEnPivot = prevData.hasReferenceTranslation === true;

  return [{
    json: {
      success: true,
      translation: content,
      method: usedEnPivot ? 'en_pivot' : 'direct',
      used_en_reference: usedEnPivot,
      tokens: {
        input_tokens: usage.input_tokens || 0,
        output_tokens: usage.output_tokens || 0
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: { code: 'PARSE_ERROR', message: e.message }
    }
  }];
}

// ── Préparer la vérification de traduction (azy.daily#541) ──────────────────
// Converge les trois sorties (structured, fallback, direct) vers une relecture
// par un second modèle, chez n'importe quel fournisseur via llm-call-messages.
//
// ⚠️ CETTE ÉTAPE N'ÉCRASE RIEN. Elle demande un avis et le joint au résultat.
// La traduction livrée reste celle du traducteur. Raison : une divergence peut
// être minuscule en caractères et décisive en sens — le sens d'un mot, une
// nuance de registre. Aucun seuil calculable ici ne mesure le sens, donc nous
// ne laissons pas un workflow arbitrer. Les deux versions sortent côte à côte.
const resultat = $input.first().json;
const pd = $('Parse Input').first().json;

// Une traduction en échec ne se vérifie pas.
if (resultat.success !== true || !resultat.translation) {
  return [{ json: Object.assign({}, resultat, { verifyActive: false, verification: null,
    verify_skipped: 'traduction_absente' }) }];
}
if (!pd.verifyActive) {
  return [{ json: Object.assign({}, resultat, { verifyActive: false, verification: null,
    verify_skipped: pd.verifySautee || 'desactivee' }) }];
}

// L'invite demande explicitement de signaler les écarts de SENS, y compris
// ceux qui ne changent presque rien au texte — c'est le cas que nous voulons
// voir, et celui qu'un contrôle automatique ne saurait pas détecter.
const instruction = [
  'Tu relis une traduction de texte talmudique. Tu ne la remplaces pas.',
  '',
  'Signale en priorite les ecarts de SENS, meme minuscules en nombre de mots',
  "(sens d'un terme, nuance, registre, negation, portee d'une proposition).",
  'Un ecart court peut etre le plus grave. Ne te limite pas aux fautes visibles.',
  '',
  'Reponds UNIQUEMENT par un objet JSON, sans texte autour et sans balises de code :',
  '{ "approved": true|false, "confidence": 0.0-1.0,',
  '  "issues": [{ "severite": "sens"|"style"|"forme", "extrait": "...", "explication": "..." }],',
  '  "suggestion": "ta propre traduction, ou null si tu approuves",',
  '  "notes": "..." }'
].join('\n');

const corps = [
  'Original (' + pd.sourceLangName + ') :',
  pd.text,
  '',
  resultat.english_pivot ? 'Pivot anglais :\n' + resultat.english_pivot + '\n' : '',
  'Traduction a relire (' + pd.targetLangName + ') :',
  resultat.translation
].filter(Boolean).join('\n');

return [{ json: Object.assign({}, resultat, {
  verifyActive: true,
  verify_skipped: null,
  _verify: {
    provider: pd.verifyProvider,
    model: pd.verifyModel,
    api_key: pd.verifyCle,
    max_tokens: 2000,
    temperature: 0,
    system: instruction,
    messages: [{ role: 'user', content: corps }]
  }
}) }];

// ── Appliquer la vérification — ANNOTE, ne substitue jamais ─────────────────
// Trois états possibles, et aucun ne modifie `translation` :
//   verification = null   → non demandée, pas de clé, ou relecture indisponible
//   approved true         → le relecteur est d'accord
//   approved false        → DÉSACCORD CONSERVÉ : `verification.suggestion` porte
//                           sa proposition, `issues` les écarts relevés.
// L'appelant décide. C'est volontairement non résolu ici : un écart de sens
// peut tenir à un mot, et aucun calcul local ne distingue une correction
// décisive d'une réécriture abusive.
const entree = $input.first().json;
const prec = $('Préparer Vérification').first().json;
const base = Object.assign({}, prec);
delete base._verify;

const brut = entree.body !== undefined ? entree.body : entree;
const code = entree.statusCode || 200;

const vide = (raison) => [{ json: Object.assign({}, base, {
  verification: null, verify_skipped: raison }) }];

if (code >= 400) return vide('relecteur_http_' + code);

// Le texte rendu par llm-call-messages, quel que soit le fournisseur.
const texte = brut && (brut.content || brut.text || brut.message || '');
if (!texte || typeof texte !== 'string') return vide('relecteur_reponse_vide');

// Analyse tolérante : aucun fournisseur ne garantit du JSON nu. On retire les
// balises de code, puis on isole le premier objet. Un échec d'analyse n'est pas
// une erreur de traduction — on rend la traduction sans avis.
let avis = null;
try {
  let s = texte.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const d = s.indexOf('{'), fin = s.lastIndexOf('}');
  if (d >= 0 && fin > d) s = s.slice(d, fin + 1);
  avis = JSON.parse(s);
} catch (e) {
  return vide('relecteur_json_illisible');
}
if (!avis || typeof avis !== 'object') return vide('relecteur_json_illisible');

const approuve = avis.approved !== false;
const confiance = typeof avis.confidence === 'number' ? avis.confidence : null;

return [{ json: Object.assign({}, base, {
  // `translation` est intacte, et le reste ci-dessous ne fait que l'éclairer.
  verification: {
    provider: prec._verify.provider,
    model: prec._verify.model,
    approved: approuve,
    confidence: confiance,
    issues: Array.isArray(avis.issues) ? avis.issues : [],
    // La proposition du relecteur n'est conservée QUE s'il désapprouve, et
    // elle n'est jamais promue en `translation`.
    suggestion: approuve ? null : (avis.suggestion || null),
    notes: avis.notes || null,
    // Vrai dès qu'il y a un désaccord : c'est le signal qu'une relecture
    // humaine est utile. Personne ne l'arbitre automatiquement.
    divergence: !approuve
  },
  verify_skipped: null
}) }];

